properties.chat:
{
  "type": "record",
  "name": "Chat",
  "namespace": "com.example.chat",
  "doc": "Chat metadata; mirrors the CQL chats table",
  "fields": [
    {
      "name": "chat_id",
      "type": { "type": "string", "logicalType": "uuid" },
      "doc": "Primary key of the chat"
    },
    {
      "name": "created_at",
      "type": { "type": "long", "logicalType": "timestamp-millis" },
      "doc": "When the chat was created (UTC epoch millis)"
    },
    {
      "name": "chat_name",
      "type": ["null", "string"],
      "default": null,
      "doc": "Optional display name for the chat"
    },
    {
      "name": "participants",
      "type": {
        "type": "array",
        "items": { "type": "string", "logicalType": "uuid" }
      },
      "default": [],
      "doc": "Member user_ids (3 or more); mirrors CQL set<uuid>, uniqueness enforced by the application. Each member's SSO identity (authenticator, principal, joined_at) lives on the ChatByUser record, not here."
    }
  ]
}

properties.message_by_chat:
{
  "type": "record",
  "name": "MessageByChat",
  "namespace": "com.example.chat",
  "doc": "A single chat message; mirrors the CQL messages_by_chat table. Date and hour are carried as a single timestamp-millis field (sent_at); the writer derives msg_date and msg_hour from it when binding to Cassandra.",
  "fields": [
    {
      "name": "chat_id",
      "type": { "type": "string", "logicalType": "uuid" },
      "doc": "Chat the message belongs to (part of the CQL partition key)"
    },
    {
      "name": "sent_at",
      "type": { "type": "long", "logicalType": "timestamp-millis" },
      "doc": "When the message was sent (UTC epoch millis). Source of truth for msg_date (UTC day) and msg_hour (UTC hour 0-23) in the CQL table, and the final clustering column that identifies the row"
    },
    {
      "name": "sender_id",
      "type": { "type": "string", "logicalType": "uuid" },
      "doc": "User id of the sender"
    },
    {
      "name": "body",
      "type": "string",
      "doc": "Message text (required)"
    }
  ]
}

properties.chat_by_user:
{
  "type": "record",
  "name": "ChatByUser",
  "namespace": "com.example.chat",
  "doc": "Reverse lookup of chat membership; mirrors the CQL chats_by_user table",
  "fields": [
    {
      "name": "user_id",
      "type": { "type": "string", "logicalType": "uuid" },
      "doc": "The member's user id (partition key in CQL)"
    },
    {
      "name": "chat_id",
      "type": { "type": "string", "logicalType": "uuid" },
      "doc": "The chat this user belongs to (clustering key in CQL)"
    },
    {
      "name": "joined_at",
      "type": { "type": "long", "logicalType": "timestamp-millis" },
      "doc": "When the user joined the chat (UTC epoch millis)"
    },
    {
      "name": "authenticator",
      "type": "string",
      "doc": "SSO mechanism that authenticated this member, e.g. 'openid', 'oidc', 'saml', 'google-oauth2'. Names a third-party single sign-on scheme, not a local password"
    },
    {
      "name": "principal",
      "type": "string",
      "doc": "External login identifier asserted by the authenticator, e.g. 'alice.nguyen' or 'bmartinez@example.com'. Human-meaningful, NOT a UUID; user_id remains the key for joins"
    }
  ]
}

properties.message:
{
  "type": "record",
  "name": "IngestedChatMessage",
  "namespace": "com.example.chat",
  "doc": "Parent envelope for a single ingested chat message. Carries the superset of fields needed to project three downstream records: Chat (chat metadata), ChatByUser (one membership row per participant), and MessageByChat (the message itself). A NiFi/stream processor reads one of these and writes to all three Cassandra tables.",
  "fields": [
    {
      "name": "chat_id",
      "type": { "type": "string", "logicalType": "uuid" },
      "doc": "Shared key. -> Chat.chat_id, ChatByUser.chat_id, MessageByChat.chat_id"
    },
    {
      "name": "created_at",
      "type": { "type": "long", "logicalType": "timestamp-millis" },
      "doc": "-> Chat.created_at (UTC epoch millis)"
    },
    {
      "name": "chat_name",
      "type": ["null", "string"],
      "default": null,
      "doc": "-> Chat.chat_name (optional display name)"
    },
    {
      "name": "participants",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "Participant",
          "doc": "One chat member and when they joined.",
          "fields": [
            {
              "name": "user_id",
              "type": { "type": "string", "logicalType": "uuid" },
              "doc": "Stable internal identifier for the member. -> ChatByUser.user_id; projected into Chat.participants. This is the system's own UUID, distinct from the externally supplied principal below."
            },
            {
              "name": "authenticator",
              "type": "string",
              "doc": "Identity provider / SSO mechanism that authenticated this member, e.g. 'openid', 'oidc', 'saml', 'google-oauth2', 'okta-saml'. Names a third-party single sign-on scheme rather than a local password; qualifies how 'principal' should be interpreted and which IdP to trust it against."
            },
            {
              "name": "principal",
              "type": "string",
              "doc": "The subject/username as asserted by the authenticator, e.g. 'alice.nguyen', 'bmartinez@example.com', or an IdP subject claim. A human-meaningful login identifier, NOT a UUID; do not use in place of user_id for keys or joins."
            },
            {
              "name": "joined_at",
              "type": { "type": "long", "logicalType": "timestamp-millis" },
              "doc": "When this member joined the chat (UTC epoch millis). -> ChatByUser.joined_at"
            }
          ]
        }
      },
      "doc": "3 or more members. Project user_id values into Chat.participants (set<uuid>); expand into one ChatByUser row per element (user_id, chat_id, joined_at)"
    },
    {
      "name": "sent_at",
      "type": { "type": "long", "logicalType": "timestamp-millis" },
      "doc": "-> MessageByChat.sent_at (UTC epoch millis). Source of truth for the msg_date/msg_hour partition and clustering keys, and the final clustering column that identifies the row"
    },
    {
      "name": "sender_id",
      "type": { "type": "string", "logicalType": "uuid" },
      "doc": "-> MessageByChat.sender_id. Must be one of participants[].user_id"
    },
    {
      "name": "body",
      "type": "string",
      "doc": "-> MessageByChat.body (required message text)"
    }
  ]
}

