    },
    {
        "name": "principal",
        "type": "string",
        "doc": "The subject/username as asserted by the authenticator, e.g. 'alice.nguyen', 'bmartinez@example.com', or an IdP subject claim. A human-meaningful login identifier, NOT a UUID; do not use in place of user_id for keys or joins."
    },
    {
        "name": "joined_at",
        "type": { "type": "long", "logicalType": "timestamp-millis" },
